import Foundation

struct DueBadge {
    let reminder: Reminder
    var now: () -> Date = Date.init

    var label: String {
        let calendar = Calendar.current
        if calendar.isDate(reminder.due, inSameDayAs: now()) { return "Today" }
        if reminder.due < now() { return "Overdue" }
        return reminder.due.formatted(date: .abbreviated, time: .omitted)
    }
}

